def choose_move(observation):
    x, y = observation['self_position']
    enemies = observation['opponent_position']
    resources = observation['resources']
    obstacles = set(observation['obstacles'])
    width = observation['grid_width']
    height = observation['grid_height']
    def dist(a, b): return abs(a[0]-b[0]) + abs(a[1]-b[1])
    target = None
    min_res_d = float('inf')
    for res in resources:
        d = dist((x,y), res)
        if d < min_res_d:
            min_res_d = d
            target = res
    move_options = []
    for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
        nx, ny = x+dx, y+dy
        if 0 <= nx < width and 0 <= ny < height and (nx,ny) not in obstacles:
            move_options.append((dx,dy))
    if target:
        def score(dx,dy):
            nx, ny = x+dx, y+dy
            return -dist((nx,ny), target)
        best = max(move_options, key=lambda m: score(*m))
        return list(best)
    # no resources, move randomly
    for dx, dy in move_options:
        return [dx, dy]
    return [0, 0]
